import React from "react";
import { graphql, Link } from "gatsby";
import SeO from '../components/seo'
import ProductCard from "./product-card";
import { HEADER_IMG, HEADER_DESCR, CRUMB } from "../config/shop";


export default function Shop({ data }) {
  const products = data.allMerchantProduct.nodes;

  return (
      <div style={{padding:`1em`}}>
	 <img src={ HEADER_IMG } alt={ HEADER_DESCR } style={{"margin":"auto","display":"block","height":"3em"}} />
        <ul className="breadcrumb">
        <li><Link to="/">Home</Link></li>
        <li>{`${CRUMB.charAt(0).toUpperCase()}${CRUMB.slice(1)}`}</li>
        </ul>
        <div id="shop">

<div className="product-grid">
  {products.map(p => (
    <ProductCard
      key={p.id}
      title={p.title}
      //price={ p.price }
      currency={ p.currency }
      description={p.description}
      image={p.imageUrl}
      merchant={p.brand || "Store"}
      url={`/${CRUMB}/${p.slug}`}
      badge={p.salePrice ? "Sale" : null}
      originalPrice={
        p.salePrice ? `${p.price} ${p.currency}` : null
      }
      price={
        p.salePrice
          ? `${p.salePrice} ${p.currency}`
          : `${p.price} ${p.currency}`
      }
    />
  ))}
	</div>
      </div>
    </div>
  );
}

export function Head({ location }) {
  return (
    <SeO
      title="Poetry and Writing Excerpts"
      description="Exerpts from poetry collections, and misc. writing from Christian Lacdael"
      pathname={location.pathname}
    />
  );
}



// new API:  allMerchantProduct(sort: {title: ASC}) {
export const query = graphql`
  query {
    site {
      siteMetadata {
	siteUrl
      }
    }
    allMerchantProduct(sort: { fields: title, order: ASC }) {
      nodes {
        id
        title
        slug
        price
        currency
        imageUrl
	description
	}
    }
  }
`;
